<script setup lang="ts">
const api=useApi(); const name=ref('Tichodrome — Rennes'), taxonQuery=ref('Tichodroma muraria'), taxonId=ref<number>(), results=ref<any[]>([])
const frequency=ref(30), windowMinutes=ref(10080), lat=ref(48.1173),lng=ref(-1.6778),radius=ref(30),sources=ref(['gbif','inaturalist']),message=ref(''),error=ref('')
async function search(){results.value=(await api<any>('/taxa/search',{query:{q:taxonQuery.value}})).data}
function select(t:any){taxonId.value=t.id;taxonQuery.value=t.scientific_name;results.value=[]}
async function save(){try{const r=await api<any>('/monitoring',{method:'POST',body:{name:name.value,taxon_id:taxonId.value,date_from:new Date().toISOString().slice(0,10),date_to:new Date().toISOString().slice(0,10),zone:{type:'radius',latitude:lat.value,longitude:lng.value,radius_km:radius.value},sources:sources.value,frequency_minutes:frequency.value,window_minutes:windowMinutes.value,is_active:true}});message.value=`Surveillance #${r.data.id} créée.`}catch(e:any){error.value=e.data?.message||e.message}}
</script>
<template><section><h1>Nouvelle surveillance</h1><div class="card"><div class="form-grid"><label>Nom<input v-model="name"></label><label style="position:relative">Taxon<input v-model="taxonQuery" @keyup.enter="search"><button class="secondary" @click="search">Chercher</button><div v-if="results.length" class="taxon-results"><button v-for="t in results" :key="t.id" @click="select(t)">{{ t.scientific_name }}</button></div></label><label>Fréquence (min)<input v-model.number="frequency" type="number" min="5"></label><label>Fenêtre (min)<input v-model.number="windowMinutes" type="number" min="5"></label><label>Latitude<input v-model.number="lat" type="number" step=".0001"></label><label>Longitude<input v-model.number="lng" type="number" step=".0001"></label><label>Rayon km<input v-model.number="radius" type="number"></label></div><p><label style="display:inline"><span><input v-model="sources" type="checkbox" value="gbif"> GBIF</span></label> <label style="display:inline"><span><input v-model="sources" type="checkbox" value="inaturalist"> iNaturalist</span></label></p><button @click="save">Créer</button><p class="success">{{ message }}</p><p class="error">{{ error }}</p></div></section></template>
